def transform(grid):
    """Connect each diagonal chain of visible markers; rays are blocked by markers."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background:
                points.setdefault(grid[r][c], []).append((r, c))

    # Same-color diagonal pairs are connected by their line segment.
    matched = set()
    for color, cells in points.items():
        for (r1, c1), (r2, c2) in combinations(cells, 2):
            dr, dc = r2 - r1, c2 - c1
            if dr != 0 and abs(dr) == abs(dc):
                matched.update(((r1, c1), (r2, c2)))
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                for k in range(abs(dr) + 1):
                    rr, cc = r1 + k * sr, c1 + k * sc
                    if grid[rr][cc] == background:
                        out[rr][cc] = color

    # Unpaired markers project along the down-right diagonal in both directions,
    # stopping upon the first non-background cell or the grid edge.
    for cells in points.values():
        for r, c in cells:
            if (r, c) in matched:
                continue
            for step in (-1, 1):
                rr, cc = r + step, c + step
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                    out[rr][cc] = grid[r][c]
                    rr += step
                    cc += step
    return out
