def transform(grid):
    """Connect same-color diagonal markers; if interrupted by another color, carry that color across the full diagonal."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background:
                points.setdefault(grid[r][c], []).append((r, c))

    lines = {}
    for color, cells in points.items():
        for (r1, c1), (r2, c2) in combinations(cells, 2):
            dr, dc = r2 - r1, c2 - c1
            if dr and abs(dr) == abs(dc):
                sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
                segment = [(r1 + k * sr, c1 + k * sc) for k in range(abs(dr) + 1)]
                key = (r1 - c1, sr == sc)
                lines.setdefault(key, []).append((color, segment, sr, sc, r1, c1))

    for entries in lines.values():
        for color, segment, sr, sc, r1, c1 in entries:
            # A distinct-color marker on the segment changes this to a full diagonal ray.
            blockers = [grid[r][c] for r, c in segment if grid[r][c] not in (background, color)]
            paint = blockers[0] if blockers and all(v == blockers[0] for v in blockers) else color
            if blockers:
                rr, cc = r1, c1
                while 0 <= rr - sr < h and 0 <= cc - sc < w:
                    rr -= sr; cc -= sc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] == background:
                        out[rr][cc] = paint
                    rr += sr; cc += sc
            else:
                for r, c in segment:
                    if grid[r][c] == background:
                        out[r][c] = paint
    return out
