from itertools import combinations


def transform(grid):
    """Connect aligned same-color pairs; crossing markers project perpendicular rays."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background:
                points.setdefault(grid[r][c], []).append((r, c))

    connectors = []
    rays = []
    for color, cells in points.items():
        for (r1, c1), (r2, c2) in combinations(cells, 2):
            dr, dc = r2 - r1, c2 - c1
            if dr == 0 or abs(dr) != abs(dc):
                continue
            sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
            segment = [(r1 + k * sr, c1 + k * sc) for k in range(abs(dr) + 1)]
            connectors.append((color, segment))
            for r, c in segment:
                marker = grid[r][c]
                if marker not in (background, color):
                    # A crossing marker emits a full perpendicular diagonal.
                    for rr in range(h):
                        cc = c - (rr - r) if sr == sc else c + (rr - r)
                        if 0 <= cc < w and grid[rr][cc] == background:
                            rays.append((rr, cc, marker))

    # Project rays first. Connectors are painted afterward and take precedence;
    # original non-background markers are always preserved.
    for r, c, color in rays:
        out[r][c] = color
    # Color 1 is the primary connector in these tasks and wins overlapping lines.
    connectors.sort(key=lambda item: item[0] == 1)
    for color, segment in connectors:
        for r, c in segment:
            if grid[r][c] == background:
                out[r][c] = color
    return out
